def compute(vars):
    asset_value = vars["v1"]
    amortization_period_years = vars["v2"]

    if amortization_period_years == 0:
        return None

    average_amortization_expense = asset_value / amortization_period_years

    return {
        "value": average_amortization_expense,
        "trace": {
            "customer_related_intangible_assets": asset_value,
            "amortization_period_years": amortization_period_years,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "per year"
            }
        }
    }
